  let pbbsUI = null;
  let bleUI = null;   // BLE Presence page (js/bleui.js)
  let rttyUI = null;    // P25X RTTY, the teleprinter round table (js/rtty.js), made in init
  let webUI = null;     // P25X Web, the text web browser (js/web.js), made in init
  let damsUI = null;    // SEQ Dam Telemetry (js/dams.js), made in init
  let dnp3UI = null;    // DNP3 Demo (js/dnp3lab.js), made in init
  let firesUI = null;   // Fire Watch (js/fires.js), made in init
  let gridMap = null;   // QLD Grid Power > SEQ Grid Map tab (js/gridmap.js), made in init
  let spaceUI = null;   // Space Weather (js/spacewx.js), made in init
  let issUI = null;     // ISS Tracker & Auto-Tuner (js/iss.js), made in init
