  // ---------------------------------------------------------------- sound
  // Alert sounds (Admin > Alert sounds): each alert plays a built-in WAV (assets/sounds/), the
  // user's own file, or the synthesised tone -- and falls back to the tone whenever a file won't play.
  // err / ok / tx always use the tone. Played with <audio>, not fetch + decodeAudioData, so it works from file://.
  const SOUND_FILES = [['msg-chime-cascade', 'Chime cascade'], ['msg-marimba', 'Marimba'], ['msg-sonar', 'Sonar'],
    ['msg-synth-pluck', 'Synth pluck'], ['preset-arrival', 'Preset arrival'], ['voice-network-msg', 'Voice: network message']];
  const ALERTS = [['msg', 'Text message'], ['preset', 'Preset message'], ['status', 'Status update'], ['bulletin', 'Bulletin'], ['call', 'Call alert'], ['emergency', 'Emergency']];
  const DEFAULT_SOUNDS = { msg: 'wav:msg-marimba', preset: 'wav:preset-arrival', status: 'wav:msg-synth-pluck', bulletin: 'wav:voice-network-msg', call: 'tone', emergency: 'tone' };
  settings.sounds = Object.assign({}, DEFAULT_SOUNDS, settings.sounds);
  if (typeof settings.soundVol !== 'number') settings.soundVol = .8;
  const CUSTOM_SOUND_MAX = 512 * 1024;   // own files live in localStorage (~5 MB for everything), so keep them small
