      try { await rawWrite(it.wire, it.opts.label); }
      catch (e) { this.cur = null; it.res({ ok: false, error: e.message, replies: [] }); setTimeout(() => this.pump(), 10); return; }
      if (state.conn.mode === 'transparent') { this.finish(); return; }
