    // start a second transfer whose chunks starved the first's resends (2026-10-10).
    if (sstvStarting || sstvActive || kellyBusy || sstvLink.sending()) { toast('⏳', 'Still sending the last picture', 'Wait for it to be delivered, or press Cancel', 'bad'); return; }
    sstvStarting = true; $('#sv-send').disabled = true;
    setTimeout(() => { sstvStarting = false; dirty('sstv'); }, 3000);
