    // sends it on out the one repeater that last heard that radio -- not every repeater on the network.
    const gw = +settings.relayId || 5059999, me = state.settingsSelf(), raw = $('#sv-dest').value.trim();
    const dest = raw ? resolveId(raw) : 0;
    if (raw && !dest) { sstvStarting = false; dirty('sstv'); toast('🤔', 'Who is that?', `"${raw}" isn't a radio ID or a name in the Directory`, 'bad'); return; }
    if (dest && dest === me) { sstvStarting = false; dirty('sstv'); toast('🤔', "That's this radio", 'Pick someone else, or leave To blank for the dashboard', 'bad'); return; }
    const p = sstvPending, call = (settings.myCall || (settings.aprs.call || '').split('-')[0] || '').toUpperCase().slice(0, 16);
    const fwd = dest && dest !== gw ? dest : 0;
