    if (e.t && radar.ask && e.t.xid === radar.ask.xid) { radarEvent(e); return; }   // rain radar request
    if (e.t && cam.ask && e.t.xid === cam.ask.xid) { camEvent(e); return; }   // club camera request
    if (e.t && obs.ask && e.t.xid === obs.ask.xid) { obsEvent(e); return; }   // BOM observations request
