    if (e.t && spaceUI && spaceUI.ownsXid(e.t.xid)) { spaceUI.kfEvent(e); return; }  // Space Weather
    if (e.t && issUI && issUI.ownsXid(e.t.xid)) { issUI.kfEvent(e); return; }  // ISS Tracker
    if (e.t && damsUI && damsUI.ownsXid(e.t.xid)) { damsUI.kfEvent(e); return; }  // SEQ Dam Telemetry
