    src.buffer = buf; f.type = filter; f.frequency.value = freq;
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(peak * settings.soundVol, t + attack); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
