          if (p.y > 1) { p.y = -0.05; p.x = Math.random(); } if (p.x > 1) p.x -= 1;
          if (kind === 'snow') { g.beginPath(); g.arc(p.x * w, p.y * h, 2, 0, 7); g.fill(); }
