    const sel = $('#wx-where'), favs = settings.wxPlaces || [];
    const want = ['rpt', 'me', ...favs.map(f => 'fav:' + f), 'town'].join('|');
    if (sel.dataset.opts !== want) {
      const keep = sel.value || settings.wxWhere || 'rpt';
      sel.innerHTML = `<option value="rpt">📡 My repeater's town</option><option value="me">📍 My position</option>${favs.map(f => `<option value="fav:${esc(f)}">⭐ ${esc(f)}</option>`).join('')}<option value="town">🔎 Another town…</option>`;
      sel.dataset.opts = want; sel.value = [...sel.options].some(o => o.value === keep) ? keep : 'rpt';
    }
