    const a = wx.ask, rx = a && rfRx(), busy = rfBusy();
    $('#wx-go').disabled = busy || !!a;
    const steps = ['asking', 'gateway', 'coming', 'done'];
    const phase = a ? (rx ? 'coming' : a.phase) : wx.data && Date.now() - (wx.data.got || 0) < 8000 ? 'done' : '';
