    $$('#wx-link .wx-step').forEach((s, i) => s.classList.toggle('lit', phase && i <= steps.indexOf(phase)));
    const lab = { asking: `Asking the P25X gateway for ${a ? a.label : ''}…`, gateway: 'The gateway has it -- fetching the forecast…',
      coming: rx ? `Forecast on its way… ${rx.chunks.size}/${rx.info ? rx.info.nchunks : '?'} chunks` : '', done: 'Here it is!' }[phase] || '';
