    $('#c-current-card').classList.toggle('live', live);
    $('#c-current-state').textContent = live ? 'LIVE' : state.radio.tx ? 'TX' : 'idle';
    $('#c-current-state').className = 'tag ' + (live ? 'ok' : state.radio.tx ? 'hot' : '');
