    $('#ins-board').innerHTML = (a.weeklyLeaderboard || []).map((r, i) => `<tr><td class="mono">${i + 1}</td><td>${i < 3 ? ['🥇', '🥈', '🥉'][i] + ' ' : ''}${esc(r.who)}</td><td class="mono" style="text-align:right">${r.count}</td></tr>`).join('') || '<tr><td colspan="3" class="dim">No transmissions this week yet</td></tr>';
    $('#ins-kerchunk').innerHTML = (a.kerchunkLeaderboard || []).map((r, i) => `<tr><td class="mono">${i + 1}</td><td>${esc(r.who)}</td><td class="mono" style="text-align:right">${r.count}</td></tr>`).join('') || '<tr><td colspan="3" class="dim">Nobody kerchunking today 👏</td></tr>';
    // userlist
    const q = ins.q.trim().toUpperCase(), key = { secs: u => -u[4], calls: u => -u[3], last: u => -u[6], call: u => u[1] || 'zzz' }[ins.sort];
    const users = ((d && d.users) || []).filter(u => !q || `${u[0]} ${u[1]} ${u[2]}`.toUpperCase().includes(q))
      .slice().sort((x, y) => { const p = key(x), r = key(y); return p < r ? -1 : p > r ? 1 : 0; });
    const top = Math.max(1, ...((d && d.users) || []).map(u => u[4]));
