    toggle('#ccr-progress', async on => (await ccrP25('C', on ? '1' : '0', { label: 'P25 progress', expect: '+' })).ok);   // 1 = on (manual has it backwards)
    toggle('#ccr-mon', async on => (await send(C.ccr.monitor(on), { label: 'CCR monitor', expect: '+' })).ok);
