      const x = r.rec; $(out).innerHTML = x ? `<b>${esc(x.callsign)}</b> · ${esc(`${x.fname} ${x.surname}`.trim())} · ${esc([x.city, x.state].filter(Boolean).join(', '))} · DMR ${esc(x.id)}${/^\d+$/.test(q.trim()) && aliasOf(q.trim()) ? ` (P25X ${esc(q.trim())})` : ''}` : `<span class="dim">${esc(q)}: not found</span>`;
