    // charts
    [$('#d-rssi-chart'), $('#tl-chart')].forEach(wireChartHover);
    window.addEventListener('resize', () => dirty('dash', 'telemetry'));
    document.addEventListener('visibilitychange', () => { if (!document.hidden) dirty('all'); });
