  function keeperPost(final) {
    let s; try { s = JSON.stringify(keeperLog()); } catch { return; }
    if (!final && s === keeperSent) return;
    keeperSent = s;
    fetch('/api/keeper-store', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: `{"at":${Date.now()},${s.slice(1)}` })
      .catch(() => { keeperSent = ''; });   // bridge restarting: try again next time
  }
